<div id="kt_content_container" class="container-xxl py-5">
    <div class="d-flex flex-wrap flex-stack mb-7"><div><h1 class="fw-bold text-gray-900 mb-2">Carrito de Compras</h1><div class="text-muted fs-6">Revisa tus productos antes de confirmar el pedido</div></div><button type="button" id="vaciar_carrito" class="btn btn-light-danger"><i class="ki-outline ki-trash fs-2"></i>Vaciar carrito</button></div>
    <div id="alerta-carrito"></div>
    <div id="contenido_carrito"></div>
</div>

<script>
(function () {
    const contenido = document.getElementById('contenido_carrito'), alerta = document.getElementById('alerta-carrito');
    function obtenerCarrito() { return JSON.parse(localStorage.getItem('carrito_productos') || '[]'); }
    function guardarCarrito(carrito) { localStorage.setItem('carrito_productos', JSON.stringify(carrito)); mostrarCarrito(); }
    function mostrarCarrito() {
        const carrito = obtenerCarrito();
        if (!carrito.length) { contenido.innerHTML = '<div class="card card-flush"><div class="card-body text-center py-20"><i class="ki-outline ki-handcart fs-5x text-muted"></i><h3 class="text-gray-800 mt-5">Tu carrito está vacío</h3><p class="text-muted">Agrega productos desde su página de detalle.</p></div></div>'; document.getElementById('vaciar_carrito').disabled = true; return; }
        document.getElementById('vaciar_carrito').disabled = false;
        const total = carrito.reduce((suma, item) => suma + (Number(item.precio) * Number(item.cantidad)), 0);
        contenido.innerHTML = '<div class="row g-7"><div class="col-xl-8"><div class="card card-flush"><div class="card-header"><h3 class="card-title fw-bold">Productos seleccionados</h3></div><div class="card-body pt-0">' + carrito.map(item => '<div class="d-flex align-items-center border-bottom py-5"><div class="symbol symbol-75px me-5"><img src="' + (item.imagen || 'assets/media/products/default.png') + '" alt="Producto" /></div><div class="flex-grow-1"><span class="text-gray-800 fw-bold fs-5">' + item.nombre + '</span><span class="text-muted d-block fs-7">$' + Number(item.precio).toFixed(2) + ' MXN por unidad</span><div class="d-flex align-items-center mt-3"><button class="btn btn-icon btn-sm btn-light disminuir-cantidad" data-id="' + item.id_producto + '">-</button><span class="mx-3 fw-bold">' + item.cantidad + '</span><button class="btn btn-icon btn-sm btn-light aumentar-cantidad" data-id="' + item.id_producto + '">+</button><span class="text-muted fs-7 ms-5">Máximo: ' + item.stock + '</span></div></div><div class="text-end"><span class="text-primary fw-bold fs-4">$' + (Number(item.precio) * Number(item.cantidad)).toFixed(2) + '</span><button class="btn btn-sm btn-light-danger d-block mt-3 eliminar-producto" data-id="' + item.id_producto + '">Eliminar</button></div></div>').join('') + '</div></div></div><div class="col-xl-4"><div class="card card-flush"><div class="card-header"><h3 class="card-title fw-bold">Resumen</h3></div><div class="card-body"><div class="d-flex justify-content-between mb-5"><span class="text-muted">Productos</span><span class="fw-bold">' + carrito.reduce((suma, item) => suma + Number(item.cantidad), 0) + '</span></div><div class="separator separator-dashed mb-5"></div><div class="d-flex justify-content-between"><span class="fs-4 fw-bold">Total</span><span class="text-primary fs-2 fw-bold">$' + total.toFixed(2) + ' MXN</span></div><button type="button" id="confirmar_pedido" class="btn btn-primary w-100 mt-7"><i class="ki-outline ki-check fs-2"></i>Confirmar pedido</button></div></div></div></div>';
        $('.aumentar-cantidad').on('click', function () { cambiarCantidad($(this).data('id'), 1); }); $('.disminuir-cantidad').on('click', function () { cambiarCantidad($(this).data('id'), -1); }); $('.eliminar-producto').on('click', function () { guardarCarrito(obtenerCarrito().filter(item => String(item.id_producto) !== String($(this).data('id')))); }); $('#confirmar_pedido').on('click', confirmarPedido);
    }
    function cambiarCantidad(id, cambio) { const carrito = obtenerCarrito(), item = carrito.find(producto => String(producto.id_producto) === String(id)); if (item) item.cantidad = Math.max(1, Math.min(Number(item.cantidad) + cambio, Number(item.stock))); guardarCarrito(carrito); }
    function confirmarPedido() { const carrito = obtenerCarrito(), total = carrito.reduce((suma, item) => suma + (Number(item.precio) * Number(item.cantidad)), 0), productos = carrito.map(item => ({ id_producto: item.id_producto, cantidad: item.cantidad, precio: item.precio })); const datos = new FormData(); datos.append('total', total.toFixed(2)); datos.append('productos', JSON.stringify(productos)); fetch('actions/15.create_pedido.php', { method: 'POST', body: datos }).then(r => r.json()).then(respuesta => { if (respuesta.success) { localStorage.removeItem('carrito_productos'); mostrarCarrito(); alerta.innerHTML = '<div class="alert alert-success">' + respuesta.message + '</div>'; } else alerta.innerHTML = '<div class="alert alert-danger">' + (respuesta.error || 'No se pudo confirmar el pedido.') + '</div>'; }).catch(() => alerta.innerHTML = '<div class="alert alert-danger">Ocurrió un error de conexión.</div>'); }
    document.getElementById('vaciar_carrito').addEventListener('click', function () { localStorage.removeItem('carrito_productos'); mostrarCarrito(); }); mostrarCarrito();
})();
</script>
